function completedCompetitionMatches(){syncClubGamesToFixtures();return seasonCompetitionFixtures().filter(m=>m.homeScore!==''&&m.awayScore!==''&&m.home&&m.away)}
function resultForTeam(m,team){team=canonicalTeamName(team);const home=canonicalTeamName(m.home)===team;const gf=Number(home?m.homeScore:m.awayScore),ga=Number(home?m.awayScore:m.homeScore);if(!Number.isFinite(gf)||!Number.isFinite(ga))return '';return gf>ga?'V':gf<ga?'D':'E'}
