 return `<div class="recent-games-strip">${slots.map(x=>{if(!x)return `<div class="recent-game-card empty"><div class="recent-game-logo">—</div><div class="recent-contrib">—</div><div class="discipline-icons"><span class="mini-card yellow"></span><span class="mini-card red"></span></div></div>`;const g=x.g;return `<button class="recent-game-card" type="button" data-recent-game="${esc(g.id)}" title="${esc(gameTitle(g))} · ${fmtDate(g.date)}"><div class="recent-game-logo">${teamLogoHtml(g.opponent,'recent')}</div><div class="recent-opponent">${esc(teamByName(g.opponent)?.short||g.opponent)}</div><div class="recent-contrib">${esc(contributionText(x))}</div><div class="discipline-icons"><span class="mini-card yellow ${x.yellow?'active':''}" title="${x.yellow?`${x.yellow} amarelo(s)`:'Sem amarelo'}"></span><span class="mini-card red ${x.red?'active':''}" title="${x.red?`${x.red} vermelho(s)`:'Sem vermelho'}"></span></div></button>`}).join('')}</div>`;
