function openJoinRequest(){openModal('Aderir ao ADC Figueiras','Pedido de acesso à futura plataforma online.',`<form id="joinForm"><div class="form-grid"><div class="field"><label>Nome</label><input name="name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field full"><label>Quero aderir como</label><select name="kind"><option value="member">Sócio</option><option value="player">Atleta</option></select></div></div><div class="form-actions"><button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn">Enviar pedido</button></div></form>`);$('#joinForm').onsubmit=e=>{e.preventDefault();state.joinRequests=state.joinRequests||[];state.joinRequests.push({id:uid('jr'),...Object.fromEntries(new FormData(e.target)),createdAt:new Date().toISOString(),status:'pending'});closeModal();saveState('Pedido registado nesta preview. Na versão online seguirá para a administração.')};$('[data-close]').onclick=closeModal}

function renderGames(){
 syncClubGamesToFixtures();
 const rows=[...seasonGames()].sort((a,b)=>dateTimeOf(a.date,a.time)-dateTimeOf(b.date,b.time));
 $('#view-games').innerHTML=`<div class="section-head"><div><h2>Jogos · ${esc(activeSeason()?.label||'')}</h2><p>Calendário do ADC Figueiras e fichas de jogo.</p></div>${canEdit()?'<button class="btn" id="addGame">＋ Outro jogo</button>':''}</div>${rows.length?rows.map(g=>`<div class="game-card ${g.fixtureId?'league-game-card':''}"><div class="when"><strong>${fmtShort(g.date).split(' ')[0]}</strong><small>${fmtShort(g.date).split(' ').slice(1).join(' ')}</small></div>${teamLogoHtml(g.opponent,'game-logo')}<div class="main-info"><h4>${esc(gameTitle(g))}</h4><p>${g.round?`Jornada ${esc(g.round)} · `:''}${esc(g.competition||'Jogo')} · ${esc(g.time||'Hora por definir')}${g.venue?` · ${esc(g.venue)}`:''}</p></div><div>${g.status==='final'||(g.homeScore!==''&&g.awayScore!=='')?`<span class="score">${scoreText(g)}</span>`:pill('Agendado','blue')}</div><div class="inline-actions"><button class="btn secondary sm open-game" data-id="${g.id}">Match Center</button>${canEdit()?`<button class="btn secondary sm edit-game" data-id="${g.id}">Editar</button>`:''}</div></div>`).join(''):empty('Ainda não existem jogos')}`;
 $('#addGame')&&($('#addGame').onclick=openGameCreate);
 $$('.open-game').forEach(b=>b.onclick=()=>{sessionStorage.setItem('mcGame',b.dataset.id);showView('matchcenter')});
 $$('.edit-game').forEach(b=>b.onclick=()=>openGameManage(b.dataset.id));
}

function openGameCreate(){openModal('Novo jogo','Adiciona o jogo à época ativa.',`<form id="gameForm"><div class="form-grid"><div class="field"><label>Data *</label><input type="date" name="date" value="${nowKey()}" required></div><div class="field"><label>Hora</label><input type="time" name="time"></div><div class="field"><label>Jornada</label><input type="number" min="1" name="round"></div><div class="field full"><label>Adversário *</label><input name="opponent" required></div><div class="field"><label>Casa / Fora</label><select name="homeAway"><option>Casa</option><option>Fora</option></select></div><div class="field"><label>Competição</label><input name="competition" placeholder="Campeonato / Taça / Amigável"></div><div class="field"><label>Classificação</label><label class="check-inline"><input type="checkbox" name="countsForStandings" checked> Conta para a classificação</label></div><div class="field full"><label>Pavilhão / local</label><input name="venue"></div></div><div class="form-actions"><button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn">Criar jogo</button></div></form>`);$('#gameForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target);const d=Object.fromEntries(fd);d.countsForStandings=fd.get('countsForStandings')==='on';const roster={};state.players.forEach(p=>roster[p.id]={status:'Não convocado',starter:false,used:false,stats:{goals:0,assists:0,yellow:0,red:0}});const g={id:uid('g'),seasonId:state.settings.activeSeasonId,...d,status:'scheduled',homeScore:'',awayScore:'',roster,timeline:[]};state.games.push(g);closeModal();saveState();sessionStorage.setItem('mcGame',g.id);showView('matchcenter')};$('[data-close]').onclick=closeModal}

function openGameManage(id){
 const g=state.games.find(x=>x.id===id);if(!g)return;g.roster=g.roster||{};
 const roster=state.players.map(p=>{const r=g.roster[p.id]||{status:'Não convocado',starter:false,used:false};const status=normalizeRosterStatus(r.status);return `<div class="list-row roster-manage-row" data-rp="${p.id}"><div class="roster-player-meta"><div>${playerHtml(p)}</div>${pill(normalizePlayerStatus(p.status),statusPillType(p.status))}</div><div class="inline-actions roster-controls"><select class="roster-status"><option ${status==='Convocado'?'selected':''}>Convocado</option><option ${status==='Não convocado'?'selected':''}>Não convocado</option><option ${status==='Lesionado'?'selected':''}>Lesionado</option><option ${status==='Suspenso'?'selected':''}>Suspenso</option><option ${status==='Ausente'?'selected':''}>Ausente</option><option ${status==='Em dúvida'?'selected':''}>Em dúvida</option></select><label class="check-inline"><input type="checkbox" class="roster-used" ${r.used===true||r.starter?'checked':''}> Jogou</label><label class="check-inline"><input type="checkbox" class="roster-starter" ${r.starter?'checked':''}> 5 inicial</label><label class="check-inline captain-choice"><input type="radio" name="gameCaptain" class="roster-captain" ${g.captainId===p.id?'checked':''}> Capitão</label></div></div>`}).join('');
 openModal(gameTitle(g),`${fmtDate(g.date)} · ${esc(g.competition||'Jogo')}`,`<div class="form-grid"><div class="field"><label>Data</label><input id="gDate" type="date" value="${esc(g.date)}"></div><div class="field"><label>Hora</label><input id="gTime" type="time" value="${esc(g.time||'')}"></div><div class="field"><label>Jornada</label><input id="gRound" type="number" min="1" value="${esc(g.round||'')}"></div><div class="field"><label>Golos Figueiras</label><input id="gHome" type="number" min="0" value="${esc(g.homeScore)}"></div><div class="field"><label>Golos adversário</label><input id="gAway" type="number" min="0" value="${esc(g.awayScore)}"></div><div class="field"><label>Estado</label><select id="gStatus"><option value="scheduled" ${g.status==='scheduled'?'selected':''}>Agendado</option><option value="final" ${g.status==='final'?'selected':''}>Final</option></select></div><div class="field"><label>Figueiras ao intervalo</label><input id="gHalfHome" type="number" min="0" value="${esc(g.halfTimeHomeScore??'')}"></div><div class="field"><label>Adversário ao intervalo</label><input id="gHalfAway" type="number" min="0" value="${esc(g.halfTimeAwayScore??'')}"></div><div class="field"><label>Classificação</label><label class="check-inline"><input id="gCounts" type="checkbox" ${(g.countsForStandings!==false&&!/taça|taca|amig|prepar|torneio/.test(String(g.competition||'').toLowerCase()))?'checked':''}> Conta para a classificação</label></div><div class="field full"><label>Local</label><input id="gVenue" value="${esc(g.venue||'')}"></div></div><div class="note subtle-note">O resultado ao intervalo é informação secundária na ficha. Nos jogos de campeonato, o intervalo é sempre aos 25 minutos.</div><div class="card-head" style="margin-top:18px"><div><h3>Convocatória e utilização</h3><p>Um convocado pode não ser utilizado. O 5 inicial e o capitão contam automaticamente como utilizados.</p></div><button class="btn secondary sm" id="allCalled">Convocar todos</button></div><div class="list">${roster}</div><div class="form-actions"><button class="btn danger" id="deleteGame">Eliminar</button><span style="flex:1"></span><button class="btn secondary" data-close>Fechar</button><button class="btn" id="saveGame">Guardar</button></div>`,true);
 $('#allCalled').onclick=()=>$$('.roster-status').forEach(s=>s.value='Convocado');
 $$('.roster-starter').forEach(cb=>cb.onchange=()=>{if(cb.checked){const row=cb.closest('[data-rp]');$('.roster-status',row).value='Convocado';$('.roster-used',row).checked=true}});
 $$('.roster-used').forEach(cb=>cb.onchange=()=>{if(cb.checked){const row=cb.closest('[data-rp]');$('.roster-status',row).value='Convocado'}});
 $$('.roster-captain').forEach(cb=>cb.onchange=()=>{if(cb.checked){const row=cb.closest('[data-rp]');$('.roster-status',row).value='Convocado';$('.roster-used',row).checked=true}});
 $('#saveGame').onclick=()=>{g.date=$('#gDate').value;g.time=$('#gTime').value;g.round=$('#gRound')?.value||g.round||'';g.homeScore=$('#gHome').value;g.awayScore=$('#gAway').value;g.halfTimeHomeScore=$('#gHalfHome').value;g.halfTimeAwayScore=$('#gHalfAway').value;g.status=$('#gStatus').value;g.countsForStandings=$('#gCounts').checked;g.venue=$('#gVenue').value;let starters=0;let captainId='';$$('[data-rp]').forEach(row=>{g.roster[row.dataset.rp]=g.roster[row.dataset.rp]||{stats:{}};const starter=$('.roster-starter',row).checked;const isCaptain=$('.roster-captain',row).checked;const used=starter||isCaptain||$('.roster-used',row).checked;const status=(starter||used||isCaptain)?'Convocado':$('.roster-status',row).value;g.roster[row.dataset.rp].status=status;g.roster[row.dataset.rp].starter=starter;g.roster[row.dataset.rp].used=status==='Convocado'?used:false;if(starter)starters++;if(isCaptain)captainId=row.dataset.rp});if(starters>5){alert('Só podes selecionar até 5 jogadores para o 5 inicial.');return;}g.captainId=captainId;closeModal();saveState('Jogo atualizado.')};
 $('#deleteGame').onclick=()=>{if(confirm('Eliminar este jogo?')){state.games=state.games.filter(x=>x.id!==g.id);closeModal();saveState('Jogo eliminado.')}};$('[data-close]').onclick=closeModal;
}

function renderMatchCenter(){
 let id=sessionStorage.getItem('mcGame');let g=state.games.find(x=>x.id===id);if(!g){g=[...seasonGames()].sort((a,b)=>Math.abs(dateTimeOf(a.date,a.time)-new Date())-Math.abs(dateTimeOf(b.date,b.time)-new Date()))[0]}if(!g){$('#view-matchcenter').innerHTML=empty('Sem jogos','Cria um jogo para abrir o Match Center.');return}sessionStorage.setItem('mcGame',g.id);
 let events=[...(g.timeline||[])];if(isLeagueGame(g)&&!events.some(e=>e.type==='halftime'))events.push({id:'auto_halftime',type:'halftime',minute:25,text:'Intervalo'});events=events.sort((a,b)=>(Number(a.minute)||999)-(Number(b.minute)||999));
 const calledEntries=Object.entries(g.roster||{}).filter(([,r])=>r.status==='Convocado');const called=calledEntries.map(([id])=>playerById(id)).filter(Boolean);const starters=Object.entries(g.roster||{}).filter(([,r])=>r.starter).map(([id])=>playerById(id)).filter(Boolean).sort((a,b)=>{const aGK=String(a.position||'').toUpperCase()==='GR',bGK=String(b.position||'').toUpperCase()==='GR';if(aGK!==bGK)return aGK?-1:1;const an=Number(a.number),bn=Number(b.number),aNum=Number.isFinite(an)&&String(a.number||'').trim()!=='',bNum=Number.isFinite(bn)&&String(b.number||'').trim()!=='';if(aNum&&bNum)return an-bn;if(aNum!==bNum)return aNum?-1:1;return String(a.number||'').localeCompare(String(b.number||''),'pt',{numeric:true})});
 const starterSlots=Array.from({length:5},(_,i)=>{const p=starters[i];if(!p)return '<div class="starter-square empty">—</div>';return `<div class="starter-square ${String(p.position||'').toUpperCase()==='GR'?'keeper':'field'}" title="${esc(p.name)}">${esc(p.number||'?')}</div>`}).join('');
 const calledTags=calledEntries.map(([pid,r])=>{const p=playerById(pid);if(!p)return '';const used=playerWasUsed(g,pid,r),captain=g.captainId===pid;return `<span class="callup-chip ${used?'used':'unused'}">${p.number?`#${esc(p.number)} · `:''}${esc(p.name)}${captain?' <b class="captain-badge">C</b>':''}${g.status==='final'?` · ${used?'utilizado':'não utilizado'}`:''}</span>`}).join('');const ht=halfTimeScoreText(g);
 $('#view-matchcenter').innerHTML=`<div class="section-head"><div><h2>Match Center</h2><p>${fmtDate(g.date)} · ${esc(g.competition||'Jogo')}</p></div><div class="inline-actions">${canEdit()?`<button class="btn secondary" id="editThisGame">Convocatória / ficha de jogo</button><button class="btn" id="addEvent">＋ Acontecimento</button>`:''}</div></div><div class="match-grid"><div class="card match-scoreboard"><div class="eyebrow">${g.status==='final'?'FINAL':'FICHA DE JOGO'}</div><div class="teams"><div class="team-name">${g.homeAway==='Casa'?'ADC Figueiras':esc(g.opponent)}</div><div class="big-score">${scoreText(g)}</div><div class="team-name">${g.homeAway==='Casa'?esc(g.opponent):'ADC Figueiras'}</div></div>${ht?`<div class="halftime-score">Intervalo · ${esc(ht)}</div>`:''}<div class="muted">${esc(g.time||'Hora por definir')} · ${esc(g.venue||'Local por definir')}</div><div class="hero-actions" style="justify-content:center">${canEdit()?`<button class="btn blue sm" id="notifGameDay">DIA DE JOGO!</button><button class="btn secondary sm" id="notifCallup">Convocatória</button><button class="btn amber sm" id="notifFood">Plano pré-jogo</button>${g.status==='final'?'<button class="btn danger sm" id="notifFinal">Resultado final</button>':''}`:''}</div><div class="card-head" style="margin-top:20px;text-align:left"><div><h3>5 inicial</h3><p>${starters.length}/5 definido</p></div></div><div class="starter-five">${starterSlots}</div><div class="card-head" style="margin-top:16px;text-align:left"><div><h3>Convocados</h3><p>${called.length} jogador(es)${g.captainId&&playerById(g.captainId)?` · Capitão: ${esc(playerById(g.captainId).name)}`:''}</p></div></div>${called.length?`<div class="callup-list">${calledTags}</div>`:empty('Convocatória por definir')}</div><div class="card"><div class="card-head"><div><h3>Cronologia</h3><p>${isLeagueGame(g)?'Intervalo automático aos 25 minutos. ':''}Golos, assistências e cartões alimentam as estatísticas.</p></div></div>${events.length?`<div class="timeline">${events.map(eventHtml).join('')}</div>`:empty('Ainda sem acontecimentos','Regista no final do jogo os marcadores, assistências e cartões.')}</div></div>`;
 $('#editThisGame')&&($('#editThisGame').onclick=()=>openGameManage(g.id));$('#addEvent')&&($('#addEvent').onclick=()=>openEventCreate(g.id));$('#notifGameDay')&&($('#notifGameDay').onclick=()=>prepareGameDayNotification(g.id));$('#notifCallup')&&($('#notifCallup').onclick=()=>prepareCallupNotification(g.id));$('#notifFood')&&($('#notifFood').onclick=()=>prepareNutritionNotifications(g.id));$('#notifFinal')&&($('#notifFinal').onclick=()=>prepareFinalNotification(g.id));
}

function eventHtml(e){const cls=e.type==='yellow'?'cardy':e.type==='red'?'cardr':e.type==='halftime'?'halftime':e.type==='note'?'note':'goal';const p=playerById(e.playerId);const a=playerById(e.assistId);const label={goal:'⚽ Golo',yellow:'🟨 Cartão amarelo',red:'🟥 Cartão vermelho',halftime:'⏸ Intervalo',note:'Nota'}[e.type]||e.type;return `<div class="timeline-event ${cls}"><div class="timeline-dot"></div><div><span class="minute">${e.minute?`${esc(e.minute)}'`:''}</span> <strong>${label}${p?` · ${esc(p.name)}`:''}</strong>${a?`<small>Assistência: ${esc(a.name)}</small>`:''}${e.text&&e.type!=='halftime'?`<small>${esc(e.text)}</small>`:''}</div></div>`}
function openEventCreate(gameId){const g=state.games.find(x=>x.id===gameId);const calledIds=Object.entries(g.roster||{}).filter(([,r])=>r.status==='Convocado').map(([id])=>id);const pool=(calledIds.length?calledIds.map(playerById).filter(Boolean):state.players);const opts=pool.map(p=>`<option value="${p.id}">${esc(p.number?`#${p.number} · ${p.name}`:p.name)}</option>`).join('');const typeOptions=`<option value="goal">Golo</option><option value="yellow">Cartão amarelo</option><option value="red">Cartão vermelho</option>${isLeagueGame(g)?'':'<option value="halftime">Intervalo</option>'}<option value="note">Nota</option>`;openModal('Novo acontecimento',gameTitle(g),`<form id="eventForm"><div class="form-grid"><div class="field"><label>Tipo</label><select name="type">${typeOptions}</select></div><div class="field"><label>Minuto</label><input name="minute" type="number" min="0" max="60"></div><div class="field"><label>Jogador</label><select name="playerId"><option value="">—</option>${opts}</select></div><div class="field"><label>Assistência</label><select name="assistId"><option value="">—</option>${opts}</select></div><div class="field full"><label>Nota</label><input name="text" placeholder="Opcional"></div></div><div class="form-actions"><button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn">Adicionar</button></div></form>`);$('#eventForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));g.timeline=g.timeline||[];g.timeline.push({id:uid('ev'),...d});[d.playerId,d.assistId].filter(Boolean).forEach(pid=>{g.roster[pid]=g.roster[pid]||{status:'Convocado',starter:false,used:true,stats:{}};g.roster[pid].status='Convocado';g.roster[pid].used=true});closeModal();saveState('Acontecimento adicionado.');renderMatchCenter()};$('[data-close]').onclick=closeModal}

function createNotification({type,title,body,audience='all',gameId='',playerId='',trigger='manual',scheduledDate=''}){const n={id:uid('n'),createdAt:new Date().toISOString(),type,title,body,audience,gameId,playerId,trigger,scheduledDate,status:'prepared',read:false};state.notifications.push(n);return n}
function prepareGameDayNotification(id){const g=state.games.find(x=>x.id===id);if(!g)return;createNotification({type:'game',title:'DIA DE JOGO!',body:`${gameTitle(g)} · ${fmtDate(g.date)}${g.time?` às ${g.time}`:''}${g.venue?` · ${g.venue}`:''}`,audience:'all',gameId:g.id,trigger:'game_day',scheduledDate:g.date});saveState('Notificação “DIA DE JOGO!” preparada.')}
function prepareCallupNotification(id){const g=state.games.find(x=>x.id===id);if(!g)return;const ids=Object.entries(g.roster||{}).filter(([,r])=>r.status==='Convocado').map(([id])=>id);if(!ids.length){toast('Ainda não há jogadores convocados.');return}ids.forEach(pid=>createNotification({type:'callup',title:'CONVOCATÓRIA',body:`Estás convocado para ${gameTitle(g)} · ${fmtDate(g.date)}${g.time?` · ${g.time}`:''}.`,audience:'player',gameId:g.id,playerId:pid,trigger:'callup'}));saveState(`Convocatória preparada para ${ids.length} jogador(es).`)}
function prepareFinalNotification(id){const g=state.games.find(x=>x.id===id);if(!g)return;createNotification({type:'final',title:'RESULTADO FINAL',body:`${gameTitle(g)} · ${scoreText(g)}`,audience:'all',gameId:g.id,trigger:'final'});saveState('Notificação de resultado final preparada.')}
function renderNutritionTemplate(template,avg,p,g){return String(template||'').replaceAll('{{peso_medio}}',avg?avg.toFixed(1):'—').replaceAll('{{jogador}}',p?.name||'Jogador').replaceAll('{{adversario}}',g?.opponent||'').replaceAll('{{hora_jogo}}',g?.time||'').replaceAll('{{data_jogo}}',fmtDate(g?.date))}
function prepareNutritionNotifications(id){const g=state.games.find(x=>x.id===id);if(!g)return;const ids=Object.entries(g.roster||{}).filter(([,r])=>r.status==='Convocado').map(([id])=>id);if(!ids.length){toast('Ainda não há jogadores convocados.');return}const day=addDays(g.date,-1);ids.forEach(pid=>{const avg=avgWeightLast14(pid,g.date);const p=playerById(pid);let body=`Jogo amanhã: ${gameTitle(g)}. `;body+=avg?`Peso médio das últimas 2 semanas: ${avg.toFixed(1)} kg. `:'Sem pesagens suficientes nas últimas 2 semanas. ';if(state.settings.nutritionEnabled&&state.settings.nutritionTemplate&&avg){body+=renderNutritionTemplate(state.settings.nutritionTemplate,avg,p,g)}else body+='Plano alimentar ainda por configurar pela equipa técnica.';createNotification({type:'food',title:'PLANO PRÉ-JOGO',body,audience:'player',gameId:g.id,playerId:pid,trigger:'day_before_game',scheduledDate:day})});saveState(`Plano pré-jogo preparado para ${ids.length} convocado(s).`)}
function noticeHtml(n){return `<div class="notice-card ${esc(n.type)}"><h4>${esc(n.title)}</h4><p>${esc(n.body)}</p><div class="notice-meta"><span>${n.scheduledDate?`Programada: ${fmtDate(n.scheduledDate)}`:new Date(n.createdAt).toLocaleString('pt-PT')}</span><span>${esc(n.audience==='all'?'Jogadores + sócios':n.audience==='players'?'Jogadores':n.audience==='members'?'Sócios':n.audience==='player'?'Jogador':'Interno')}</span></div></div>`}

function renderNotifications(){const rows=state.notifications.filter(notificationVisible).slice().reverse();$('#view-notifications').innerHTML=`<div class="section-head"><div><h2>Notificações</h2><p>Convocatórias, dia de jogo, resultados e plano pré-jogo.</p></div><div class="inline-actions"><button class="btn secondary" id="enableBrowserNotifications">Ativar no dispositivo</button>${canEdit()?'<button class="btn" id="customNotification">＋ Nova</button>':''}</div></div><div class="warning-strip">Nesta preview, as notificações ficam preparadas dentro da app e podes testar notificações imediatas do browser. O envio push agendado com a app fechada será ligado quando ativarmos o backend.</div><div style="height:12px"></div><div class="grid equal2">${rows.length?rows.map(noticeHtml).join(''):empty('Sem notificações','Ainda não existem mensagens preparadas.')}</div>`;$('#enableBrowserNotifications').onclick=requestNotificationPermission;$('#customNotification')&&($('#customNotification').onclick=openCustomNotification);state.notifications.forEach(n=>{if(notificationVisible(n))n.read=true});localStorage.setItem(V2_KEY,JSON.stringify(state));renderChrome()}
async function requestNotificationPermission(){if(!('Notification'in window)){toast('Este browser não suporta notificações.');return}const p=await Notification.requestPermission();if(p==='granted'){new Notification('ADC Figueiras',{body:'Notificações ativadas neste dispositivo.',icon:'assets/icon-192.png'});toast('Notificações ativadas.')}else toast('Permissão não concedida.')}
function openCustomNotification(){openModal('Nova notificação','Mensagem manual para a comunidade.',`<form id="notifForm"><div class="form-grid"><div class="field full"><label>Título</label><input name="title" required></div><div class="field full"><label>Mensagem</label><textarea name="body" required></textarea></div><div class="field"><label>Destinatários</label><select name="audience"><option value="all">Jogadores + sócios</option><option value="players">Jogadores</option><option value="members">Sócios</option></select></div></div><div class="form-actions"><button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn">Preparar</button></div></form>`);$('#notifForm').onsubmit=e=>{e.preventDefault();createNotification({...Object.fromEntries(new FormData(e.target)),type:'system'});closeModal();saveState('Notificação preparada.')};$('[data-close]').onclick=closeModal}

function renderTraining(){const rows=[...seasonTrainings()].sort((a,b)=>dateTimeOf(b.date,b.time)-dateTimeOf(a.date,a.time));$('#view-training').innerHTML=`<div class="section-head"><div><h2>Treinos</h2><p>Presenças registadas pela equipa técnica. Os atletas não precisam confirmar nem justificar na app.</p></div>${canEdit()?'<button class="btn" id="addTraining">＋ Novo treino</button>':''}</div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Local</th><th>Presenças</th><th>Pesagens</th><th></th></tr></thead><tbody>${rows.map(t=>{const entries=Object.values(t.entries||{});const pres=entries.filter(e=>e.status==='Presente'||e.status==='Atrasado').length;const ws=entries.filter(e=>e.pre||e.post).length;return `<tr><td><strong>${fmtDate(t.date)}</strong><div class="meta">${esc(t.time||'')}</div></td><td>${esc(t.location||'—')}</td><td>${pres}/${state.players.length}</td><td>${ws}</td><td><div class="inline-actions"><button class="btn secondary sm open-training" data-id="${t.id}">${canEdit()?'Gerir':'Ver'}</button>${canEdit()?`<button class="btn danger sm delete-training" data-id="${t.id}">Eliminar</button>`:''}</div></td></tr>`}).join('')}</tbody></table></div>`:empty('Ainda não existem treinos','Cria o primeiro treino da época.')}`;$('#addTraining')&&($('#addTraining').onclick=openTrainingCreate);$$('.open-training').forEach(b=>b.onclick=()=>openTrainingManage(b.dataset.id));$$('.delete-training').forEach(b=>b.onclick=()=>{if(confirm('Eliminar este treino?')){state.trainings=state.trainings.filter(t=>t.id!==b.dataset.id);saveState('Treino eliminado.')}})}
function openTrainingCreate(){openModal('Novo treino','Sessão de treino da época ativa.',`<form id="trainingForm"><div class="form-grid"><div class="field"><label>Data *</label><input type="date" name="date" value="${nowKey()}" required></div><div class="field"><label>Hora</label><input type="time" name="time" value="21:30"></div><div class="field full"><label>Local</label><input name="location"></div><div class="field full"><label>Notas internas</label><textarea name="notes"></textarea></div></div><div class="form-actions"><button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn">Criar treino</button></div></form>`);$('#trainingForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const t={id:uid('t'),seasonId:state.settings.activeSeasonId,...d,entries:{}};state.trainings.push(t);closeModal();saveState();openTrainingManage(t.id)};$('[data-close]').onclick=closeModal}
function openTrainingManage(id){const t=state.trainings.find(x=>x.id===id);if(!t)return;const editable=canEdit();const rows=state.players.map(p=>{const e=t.entries?.[p.id]||{};const a=Number(e.pre),b=Number(e.post),delta=a&&b?b-a:null,pct=a&&b?(b-a)/a*100:null;return `<div class="training-row" data-player="${p.id}">${playerHtml(p)}<select class="att-status" ${editable?'':'disabled'}><option value="">— Estado —</option>${['Presente','Atrasado','Falta','Lesionado'].map(s=>`<option ${e.status===s?'selected':''}>${s}</option>`).join('')}</select><input class="w-pre" type="number" step="0.1" min="0" placeholder="Antes kg" value="${esc(e.pre||'')}" ${editable?'':'disabled'}><input class="w-post" type="number" step="0.1" min="0" placeholder="Depois kg" value="${esc(e.post||'')}" ${editable?'':'disabled'}><div class="delta">${delta===null?'—':`${delta>0?'+':''}${delta.toFixed(1)} kg<br><span class="muted">${pct.toFixed(2)}%</span>`}</div></div>`}).join('');openModal(`Treino · ${fmtDate(t.date)}`,`${t.time||''}${t.location?` · ${t.location}`:''}`,`${editable?'<div class="info-strip">A equipa técnica regista presenças e pesos. Não existe confirmação/justificação pelo atleta.</div><div style="height:10px"></div>':''}<div class="training-roster">${rows}</div><div class="form-actions"><button class="btn secondary" data-close>Fechar</button>${editable?'<button class="btn" id="saveTraining">Guardar</button>':''}</div>`,true);$('#saveTraining')&&($('#saveTraining').onclick=()=>{t.entries=t.entries||{};$$('.training-row',$('#modalBody')).forEach(r=>{t.entries[r.dataset.player]={status:$('.att-status',r).value,pre:$('.w-pre',r).value,post:$('.w-post',r).value}});syncTrainingLateFines(t);closeModal();saveState('Treino atualizado.')});$('[data-close]').onclick=closeModal}

function renderWeights(){const ref=state.settings.weightReference;const cards=state.players.map(p=>{const l=latestWeight(p.id);const avg=avgWeightLast14(p.id,nowKey());return `<div class="weight-card"><div>${playerHtml(p)}</div><div><div class="weight-label">Último pré</div><div class="weight-number">${l?.pre?`${l.pre.toFixed(1)} kg`:'—'}</div></div><div><div class="weight-label">Último pós</div><div class="weight-number">${l?.post?`${l.post.toFixed(1)} kg`:'—'}</div></div><div><div class="weight-label">Média 2 semanas</div><div class="weight-number">${avg?`${avg.toFixed(1)} kg`:'—'}</div></div></div>`}).join('');$('#view-weights').innerHTML=`<div class="section-head"><div><h2>Pesagens do plantel</h2><p>Os atletas podem consultar as próprias pesagens e as dos colegas.</p></div>${canEdit()?`<span class="pill blue">Referência plano: ${ref==='pre'?'pré-treino':ref==='post'?'pós-treino':'média pré/pós'}</span>`:''}</div><div class="warning-strip">A visibilidade das pesagens está configurada de acordo com a decisão atual do clube. Antes de abrir a plataforma a todos, convém definir formalmente a política de acesso a estes dados.</div><div style="height:12px"></div><div class="grid">${cards||empty('Sem jogadores')}</div>`}

function renderSquad(){
 const stats=playerStats();const sorted=[...state.players].sort((a,b)=>{const ag=a.position==='GR'?0:1,bg=b.position==='GR'?0:1;if(ag!==bg)return ag-bg;const an=Number(a.number),bn=Number(b.number);if(Number.isFinite(an)&&Number.isFinite(bn))return an-bn;return a.name.localeCompare(b.name,'pt')});
 $('#view-squad').innerHTML=`<div class="section-head"><div><h2>Plantel</h2><p>Plantel visual, disponibilidade e estatísticas da época.</p></div>${canEdit()?'<button class="btn" id="addPlayer">＋ Jogador</button>':''}</div><div class="squad-grid">${sorted.map(p=>{const s=stats[p.id]||{};return `<article class="squad-card" data-player-profile="${p.id}"><div class="squad-card-top"><div class="squad-number ${p.position==='GR'?'keeper':'field'}">${esc(p.number||'—')}</div><div class="squad-identity"><div class="eyebrow">${esc(p.position||'Jogador')}</div><h3>${esc(p.name)}</h3>${pill(normalizePlayerStatus(p.status),statusPillType(p.status))}</div></div><div class="squad-mini-stats"><span><strong>${s.games||0}</strong> jogos</span><span><strong>${s.goals||0}</strong> G</span><span><strong>${s.assists||0}</strong> A</span></div><div class="squad-actions"><button class="btn secondary sm view-player" data-id="${p.id}">Ficha</button>${canEdit()?`<button class="btn secondary sm edit-player" data-id="${p.id}">Editar</button>`:''}</div></article>`}).join('')}</div>`;$('#addPlayer')&&($('#addPlayer').onclick=()=>openPlayer());$$('.view-player').forEach(b=>b.onclick=e=>{e.stopPropagation();openPlayerProfile(b.dataset.id)});$$('.squad-card').forEach(r=>r.onclick=()=>openPlayerProfile(r.dataset.playerProfile));$$('.edit-player').forEach(b=>b.onclick=e=>{e.stopPropagation();openPlayer(b.dataset.id)})
}
function openPlayer(id=''){
 const p=id?playerById(id):{id:'',name:'',position:'Jogador',number:'',status:'Disponível'};openModal(id?'Editar jogador':'Novo jogador','Dados básicos do plantel.',`<form id="playerForm"><div class="form-grid"><div class="field full"><label>Nome *</label><input name="name" value="${esc(p.name)}" required></div><div class="field"><label>Posição</label><select name="position"><option ${p.position==='Jogador'?'selected':''}>Jogador</option><option ${p.position==='GR'?'selected':''}>GR</option></select></div><div class="field"><label>Número</label><input name="number" value="${esc(p.number||'')}"></div><div class="field"><label>Estado</label><select name="status">${['Disponível','Lesionado','Suspenso','Ausente','Em dúvida'].map(x=>`<option ${normalizePlayerStatus(p.status)===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="form-actions"><button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn">Guardar</button></div></form>`);$('#playerForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(id)Object.assign(p,d);else state.players.push({id:uid('p'),...d});closeModal();saveState('Plantel atualizado.')};$('[data-close]').onclick=closeModal
}
function renderPlayerProfile(){
 const p=playerById(selectedPlayerId)||state.players[0];if(!p){$('#view-player').innerHTML=empty('Sem jogadores');return}selectedPlayerId=p.id;sessionStorage.setItem('playerView',p.id);const s=playerStats()[p.id]||{};const privateOk=privatePlayerAccess();const att=playerAttendanceStats(p.id);const weights=playerWeightRows(p.id);const fines=playerFineRows(p.id);const latest=weights[0];const pending=fines.filter(f=>!f.paid).reduce((sum,f)=>sum+Number(f.amount||0),0);
 $('#view-player').innerHTML=`<div class="section-head"><div><button class="back-link" id="backSquad">← Plantel</button><h2>${esc(p.name)}</h2><p>#${esc(p.number||'—')} · ${esc(p.position||'Jogador')}</p></div>${canEdit()?`<button class="btn secondary" id="editProfilePlayer">Editar jogador</button>`:''}</div><div class="player-profile-hero card"><div class="profile-number ${p.position==='GR'?'keeper':'field'}">${esc(p.number||'—')}</div><div><div class="eyebrow">${esc(p.position||'Jogador')}</div><h2>${esc(p.name)}</h2><div class="tags">${pill(normalizePlayerStatus(p.status),statusPillType(p.status))}</div></div></div><div style="height:15px"></div><div class="grid kpis player-kpis"><div class="card kpi"><div class="label">Convocatórias</div><div class="value">${s.callups||0}</div></div><div class="card kpi"><div class="label">Jogos</div><div class="value">${s.games||0}</div></div><div class="card kpi"><div class="label">Titularidades</div><div class="value">${s.starts||0}</div></div><div class="card kpi"><div class="label">Golos</div><div class="value">${s.goals||0}</div></div><div class="card kpi"><div class="label">Assistências</div><div class="value">${s.assists||0}</div></div><div class="card kpi"><div class="label">Cartões</div><div class="value cards-value"><span>🟨 ${s.yellow||0}</span><span>🟥 ${s.red||0}</span></div></div></div><div style="height:15px"></div><div class="card"><div class="card-head"><div><h3>Últimos 5 jogos</h3><p>Últimas utilizações · adversário, contribuições para golo e disciplina.</p></div></div>${playerRecentGamesHtml(p.id)}</div>${privateOk?`<div style="height:15px"></div><div class="grid two"><div class="card"><div class="card-head"><div><h3>Treinos</h3><p>Área interna.</p></div></div><div class="private-stat"><strong>${att.present}</strong><span>presenças</span></div><div class="private-stat"><strong>${att.pct}%</strong><span>assiduidade (${att.present}/${att.recorded||0})</span></div></div><div class="card"><div class="card-head"><div><h3>Pesagens</h3><p>Último registo.</p></div></div>${latest?`<div class="grid equal2"><div><div class="weight-label">Último pré</div><div class="weight-number">${latest.pre?`${Number(latest.pre).toFixed(1)} kg`:'—'}</div></div><div><div class="weight-label">Último pós</div><div class="weight-number">${latest.post?`${Number(latest.post).toFixed(1)} kg`:'—'}</div></div></div>`:empty('Sem pesagens registadas')}</div></div><div style="height:15px"></div><div class="card"><div class="card-head"><div><h3>Evolução do peso</h3><p>Visível apenas a jogadores e equipa técnica.</p></div></div>${weightChartHtml(p.id)}</div><div style="height:15px"></div><div class="card"><div class="card-head"><div><h3>Multas</h3><p>Histórico interno da época.</p></div><strong>${money(pending)} pendente</strong></div>${fines.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Motivo</th><th>Valor</th><th>Estado</th></tr></thead><tbody>${fines.map(f=>`<tr><td>${fmtDate(f.date)}</td><td>${esc(f.reason)}</td><td>${money(f.amount)}</td><td>${pill(f.paid?'Pago':'Pendente',f.paid?'green':'red')}</td></tr>`).join('')}</tbody></table></div>`:empty('Sem multas registadas')}</div>`:''}`;
 $('#backSquad').onclick=()=>showView('squad');$('#editProfilePlayer')&&($('#editProfilePlayer').onclick=()=>openPlayer(p.id));$$('[data-recent-game]').forEach(b=>b.onclick=()=>{sessionStorage.setItem('mcGame',b.dataset.recentGame);showView('matchcenter')});
}

function renderStats(){const stats=playerStats();const rows=state.players.map(p=>({p,...stats[p.id]})).sort((a,b)=>b.goals-a.goals||b.assists-a.assists);const games=seasonGames().filter(g=>g.status==='final'||(g.homeScore!==''&&g.awayScore!==''));let w=0,d=0,l=0,gf=0,ga=0;games.forEach(g=>{const a=Number(g.homeScore)||0,b=Number(g.awayScore)||0;gf+=a;ga+=b;if(a>b)w++;else if(a===b)d++;else l++});$('#view-stats').innerHTML=`<div class="grid kpis"><div class="card kpi"><div class="label">Jogos concluídos</div><div class="value">${games.length}</div></div><div class="card kpi"><div class="label">V / E / D</div><div class="value">${w}/${d}/${l}</div></div><div class="card kpi"><div class="label">Golos</div><div class="value">${gf}</div><div class="sub">marcados</div></div><div class="card kpi"><div class="label">Diferença</div><div class="value">${gf-ga>0?'+':''}${gf-ga}</div></div></div><div style="height:15px"></div><div class="card"><div class="card-head"><div><h3>Estatísticas individuais</h3><p>Dados da época ${esc(activeSeason()?.label||'')}</p></div></div><div class="table-wrap"><table><thead><tr><th>Jogador</th><th>Conv.</th><th>Jogos</th><th>5 inicial</th><th>Golos</th><th>Assist.</th><th>G+A</th><th>🟨</th><th>🟥</th></tr></thead><tbody>${rows.map(x=>`<tr class="player-profile-row" data-player-profile="${x.p.id}"><td>${playerStatHtml(x.p)}</td><td>${x.callups}</td><td>${x.games}</td><td>${x.starts}</td><td>${x.goals}</td><td>${x.assists}</td><td><strong>${x.goals+x.assists}</strong></td><td>${x.yellow}</td><td>${x.red}</td></tr>`).join('')}</tbody></table></div></div>`;$$('.player-profile-row').forEach(r=>r.onclick=()=>openPlayerProfile(r.dataset.playerProfile))}

function renderSeriesResults(){
 syncClubGamesToFixtures();
 const all=[...seasonCompetitionFixtures()].sort((a,b)=>(Number(a.round)||999)-(Number(b.round)||999)||String(a.date||'').localeCompare(String(b.date||''))||String(a.time||'').localeCompare(String(b.time||'')));
 const rounds=[...new Set(all.map(r=>String(r.round||'')).filter(Boolean))].sort((a,b)=>Number(a)-Number(b));
 const teams=(state.teams||seedTeams).map(t=>t.name).sort((a,b)=>a.localeCompare(b,'pt'));
 if(resultsRoundFilter!=='all'&&!rounds.includes(resultsRoundFilter))resultsRoundFilter='all';if(resultsTeamFilter!=='all'&&!teams.includes(resultsTeamFilter))resultsTeamFilter='all';
 const rows=all.filter(r=>(resultsRoundFilter==='all'||String(r.round||'')===resultsRoundFilter)&&(resultsTeamFilter==='all'||canonicalTeamName(r.home)===resultsTeamFilter||canonicalTeamName(r.away)===resultsTeamFilter));
 $('#view-seriesResults').innerHTML=`<div class="section-head"><div><h2>Resultados</h2><p>Calendário e resultados de toda a Série 2.</p></div>${canEdit()?'<button class="btn" id="addSeriesResult">＋ Jogo extra</button>':''}</div><div class="toolbar"><div class="field result-filter"><label>Jornada</label><select id="resultsRound"><option value="all">Todas as jornadas</option>${rounds.map(r=>`<option value="${esc(r)}" ${resultsRoundFilter===r?'selected':''}>Jornada ${esc(r)}</option>`).join('')}</select></div><div class="field result-filter"><label>Equipa</label><select id="resultsTeam"><option value="all">Todas as equipas</option>${teams.map(t=>`<option value="${esc(t)}" ${resultsTeamFilter===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div></div><div class="info-strip">Toca no nome de uma equipa para abrir a página dessa equipa. Nos jogos do ADC Figueiras, toca fora dos nomes das equipas para abrir o Match Center.</div><div style="height:12px"></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>J.</th><th>Data</th><th>Casa</th><th>Resultado</th><th>Fora</th><th></th></tr></thead><tbody>${rows.map(r=>{const club=isFigueirasTeam(r.home)||isFigueirasTeam(r.away);const score=(r.homeScore!==''&&r.awayScore!=='')?`${esc(r.homeScore)}–${esc(r.awayScore)}`:'—';return `<tr class="${club?'club-result-row':''}" ${club&&r.clubGameId?`data-club-game="${esc(r.clubGameId)}" title="Abrir Match Center"`:''}><td>${esc(r.round||'—')}</td><td>${fmtDate(r.date)}<div class="meta">${esc(r.time||'')}</div></td><td>${teamCell(r.home)}</td><td class="score">${score}</td><td>${teamCell(r.away)}</td><td>${club?'<span class="pill match-pill">Match Center</span>':canEdit()?`<div class="inline-actions"><button class="btn secondary sm edit-series-result" data-id="${r.id}">${score==='—'?'Registar':'Editar'}</button>${isExtraSeriesGame(r)?`<button class="btn danger sm delete-series-result-direct" data-id="${r.id}">Eliminar</button>`:''}</div>`:''}</td></tr>`}).join('')}</tbody></table></div>`:empty('Sem jogos para estes filtros')}`;
 $('#resultsRound').onchange=e=>{resultsRoundFilter=e.target.value;renderSeriesResults()};$('#resultsTeam').onchange=e=>{resultsTeamFilter=e.target.value;renderSeriesResults()};$('#addSeriesResult')&&($('#addSeriesResult').onclick=()=>openSeriesResult());$$('.club-result-row[data-club-game]').forEach(row=>row.onclick=e=>{if(e.target.closest('[data-team-link]'))return;sessionStorage.setItem('mcGame',row.dataset.clubGame);showView('matchcenter')});$$('.edit-series-result').forEach(b=>b.onclick=e=>{e.stopPropagation();openSeriesResult(b.dataset.id)});$$('.delete-series-result-direct').forEach(b=>b.onclick=e=>{e.stopPropagation();const r=state.competitionResults.find(x=>x.id===b.dataset.id);if(!r||!isExtraSeriesGame(r))return;if(confirm(`Eliminar o jogo ${canonicalTeamName(r.home)} – ${canonicalTeamName(r.away)}?`)){state.competitionResults=state.competitionResults.filter(x=>x.id!==r.id);saveState('Jogo extra eliminado e classificação recalculada.')}});
}

function openSeriesResult(id=''){
 const r=id?state.competitionResults.find(x=>x.id===id):{round:'',date:'',time:'',home:'',away:'',homeScore:'',awayScore:'',fixture:false};
 const teamOpts=(state.teams||seedTeams).map(t=>`<option value="${esc(t.name)}">${esc(t.name)}</option>`).join('');
 openModal(id?'Editar jogo / resultado':'Novo jogo','Jogo da Série 2.',`<form id="seriesResultForm"><div class="form-grid"><div class="field"><label>Jornada</label><input type="number" min="1" name="round" value="${esc(r.round||'')}"></div><div class="field"><label>Data</label><input type="date" name="date" value="${esc(r.date||'')}"></div><div class="field"><label>Hora</label><input type="time" name="time" value="${esc(r.time||'')}"></div><div></div><div class="field"><label>Equipa da casa</label><select name="home" required><option value="">—</option>${teamOpts}</select></div><div class="field"><label>Equipa visitante</label><select name="away" required><option value="">—</option>${teamOpts}</select></div><div class="field"><label>Golos casa</label><input type="number" min="0" name="homeScore" value="${esc(r.homeScore)}"></div><div class="field"><label>Golos fora</label><input type="number" min="0" name="awayScore" value="${esc(r.awayScore)}"></div></div><div class="form-actions">${id&&isExtraSeriesGame(r)?'<button type="button" class="btn danger" id="deleteSeriesResult">Eliminar jogo</button><span style="flex:1"></span>':''}<button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn">Guardar</button></div></form>`);
 const form=$('#seriesResultForm');form.elements.home.value=canonicalTeamName(r.home);form.elements.away.value=canonicalTeamName(r.away);
 form.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(isFigueirasTeam(d.home)||isFigueirasTeam(d.away)){alert('Os jogos do ADC Figueiras são geridos no Match Center.');return;}const homeScore=d.homeScore===''?'':Number(d.homeScore),awayScore=d.awayScore===''?'':Number(d.awayScore);if((homeScore===''&&awayScore!=='')||(homeScore!==''&&awayScore==='')){alert('Preenche os dois resultados ou deixa ambos vazios.');return;}const payload={seasonId:state.settings.activeSeasonId,...d,home:canonicalTeamName(d.home),away:canonicalTeamName(d.away),homeScore,awayScore,venue:teamByName(d.home)?.homeVenue||r.venue||'',fixture:r.fixture!==false};if(id)Object.assign(r,payload);else state.competitionResults.push({id:uid('cr'),...payload});closeModal();saveState('Jogo atualizado e classificação recalculada.')};$('#deleteSeriesResult')&&($('#deleteSeriesResult').onclick=()=>{if(confirm('Eliminar este jogo extra?')){state.competitionResults=state.competitionResults.filter(x=>x.id!==r.id);closeModal();saveState('Jogo extra eliminado e classificação recalculada.')}});
 $('[data-close]').onclick=closeModal;
}

