function openStandingRow(st,id=''){const r=id?st.rows.find(x=>x.id===id):{team:'',j:0,v:0,e:0,d:0,gf:0,ga:0,pts:0};openModal(id?'Editar classificação':'Adicionar equipa','Valores da tabela classificativa.',`<form id="standingForm"><div class="form-grid"><div class="field full"><label>Equipa</label><input name="team" value="${esc(r.team)}" required></div>${[['j','J'],['v','V'],['e','E'],['d','D'],['gf','GM'],['ga','GS'],['pts','Pts']].map(([k,l])=>`<div class="field"><label>${l}</label><input name="${k}" type="number" min="0" value="${Number(r[k])||0}"></div>`).join('')}</div><div class="form-actions">${id?'<button type="button" class="btn danger" id="delStanding">Eliminar</button>':''}<span style="flex:1"></span><button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn">Guardar</button></div></form>`);$('#standingForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(id)Object.assign(r,d);else st.rows.push({id:uid('sr'),...d});closeModal();saveState()};$('#delStanding')&&($('#delStanding').onclick=()=>{st.rows=st.rows.filter(x=>x.id!==id);closeModal();saveState()});$('[data-close]').onclick=closeModal}

function renderCalendar(){
 syncClubGamesToFixtures();
 const first=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth(),1),start=new Date(first);start.setDate(1-((first.getDay()+6)%7));
 let events=[
  ...seasonTrainings().map(t=>({date:t.date,type:'training',label:`Treino ${t.time||''}`,time:t.time||''})),
  ...seasonCompetitionFixtures().map(f=>({date:f.date,type:'game',label:`J${f.round} · ${teamByName(f.home)?.short||f.home} – ${teamByName(f.away)?.short||f.away}`,time:f.time||'',clubGameId:f.clubGameId||'',fixtureId:f.id,isClub:isFigueirasTeam(f.home)||isFigueirasTeam(f.away)}))
 ];
 if(calendarEventFilter==='club')events=events.filter(e=>e.type==='game'&&e.isClub);
 if(calendarEventFilter==='training')events=events.filter(e=>e.type==='training');
 let days='';
 for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const k=`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;const muted=d.getMonth()!==calendarCursor.getMonth();days+=`<div class="calendar-day ${muted?'muted':''} ${k===nowKey()?'today':''}"><div class="day-num">${d.getDate()}</div>${events.filter(e=>e.date===k).sort((a,b)=>String(a.time).localeCompare(String(b.time))).map(e=>`<button class="cal-event ${e.type==='game'?'game':''} ${e.isClub?'club':''}" ${e.clubGameId?`data-cal-club="${esc(e.clubGameId)}"`:e.fixtureId&&canEdit()?`data-cal-fixture="${esc(e.fixtureId)}"`:''}>${esc(e.label)}</button>`).join('')}</div>`}
 $('#view-calendar').innerHTML=`<div class="calendar-head"><button class="btn secondary sm" id="prevMonth">←</button><h2>${fmtMonth(calendarCursor)}</h2><button class="btn secondary sm" id="nextMonth">→</button></div><div class="toolbar calendar-toolbar"><div class="field result-filter"><label>Mostrar</label><select id="calendarFilter"><option value="all" ${calendarEventFilter==='all'?'selected':''}>Tudo</option><option value="club" ${calendarEventFilter==='club'?'selected':''}>Só ADC Figueiras</option><option value="training" ${calendarEventFilter==='training'?'selected':''}>Só treinos</option></select></div></div><div class="calendar-grid">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(x=>`<div class="dow">${x}</div>`).join('')}${days}</div>`;
 $('#prevMonth').onclick=()=>{calendarCursor.setMonth(calendarCursor.getMonth()-1);renderCalendar()};$('#nextMonth').onclick=()=>{calendarCursor.setMonth(calendarCursor.getMonth()+1);renderCalendar()};
 $('#calendarFilter').onchange=e=>{calendarEventFilter=e.target.value;renderCalendar()};
 $$('[data-cal-club]').forEach(b=>b.onclick=()=>{sessionStorage.setItem('mcGame',b.dataset.calClub);showView('matchcenter')});
 $$('[data-cal-fixture]').forEach(b=>b.onclick=()=>openSeriesResult(b.dataset.calFixture));
}

function renderFines(){const rows=state.fines.filter(f=>(f.seasonId||state.settings.activeSeasonId)===state.settings.activeSeasonId);const pending=rows.filter(f=>!f.paid).reduce((s,f)=>s+Number(f.amount||0),0);$('#view-fines').innerHTML=`<div class="section-head"><div><h2>Multas</h2><p>Gestão interna da equipa.</p></div><div class="inline-actions"><button class="btn secondary" id="openFineRules">Regras de multas</button><button class="btn" id="addFine">＋ Multa</button></div></div><div class="grid kpis"><div class="card kpi"><div class="label">Pendentes</div><div class="value">${money(pending)}</div></div><div class="card kpi"><div class="label">Registos</div><div class="value">${rows.length}</div></div></div><div style="height:15px"></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Jogador</th><th>Motivo</th><th>Valor</th><th>Estado</th><th>Origem</th><th></th></tr></thead><tbody>${rows.map(f=>`<tr><td>${fmtDate(f.date)}</td><td>${esc(playerById(f.playerId)?.name||'—')}</td><td>${esc(f.reason||'')}</td><td>${money(f.amount)}</td><td>${pill(f.paid?'Pago':'Pendente',f.paid?'green':'red')}</td><td>${f.auto?pill('Automática','blue'):pill('Manual','gray')}</td><td><button class="btn secondary sm toggle-fine" data-id="${f.id}">${f.paid?'Marcar pendente':'Marcar pago'}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Sem multas registadas')}`;$('#addFine').onclick=openFine;$('#openFineRules').onclick=()=>showView('fineRules');$$('.toggle-fine').forEach(b=>b.onclick=()=>{const f=state.fines.find(x=>x.id===b.dataset.id);f.paid=!f.paid;saveState()})}
function openFine(){const opts=state.players.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');const reasons=(state.fineRules||[]).map(r=>`<option value="${esc(r.reason)}"></option>`).join('');openModal('Nova multa','Registo interno.',`<form id="fineForm"><div class="form-grid"><div class="field"><label>Jogador</label><select name="playerId">${opts}</select></div><div class="field"><label>Data</label><input type="date" name="date" value="${nowKey()}"></div><div class="field full"><label>Motivo</label><input name="reason" list="fineReasons" required><datalist id="fineReasons">${reasons}</datalist></div><div class="field"><label>Valor (€)</label><input type="number" step="0.01" min="0" name="amount" required></div></div><div class="form-actions"><button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn">Guardar</button></div></form>`);$('#fineForm').onsubmit=e=>{e.preventDefault();state.fines.push({id:uid('f'),seasonId:state.settings.activeSeasonId,...Object.fromEntries(new FormData(e.target)),paid:false,auto:false});closeModal();saveState('Multa registada.')};$('[data-close]').onclick=closeModal}


function renderFineRules(){const rules=state.fineRules||[];$('#view-fineRules').innerHTML=`<div class="section-head"><div><h2>Regras de multas</h2><p>Lista de motivos e automatismos disponíveis.</p></div><button class="btn" id="addFineRule">＋ Regra</button></div>${rules.length?`<div class="table-wrap"><table><thead><tr><th>Motivo</th><th>Valor</th><th>Tipo</th><th>Estado</th><th>Descrição</th><th></th></tr></thead><tbody>${rules.map(r=>`<tr><td><strong>${esc(r.reason)}</strong></td><td>${money(r.amount)}</td><td>${r.automatic?pill('Automática','blue'):pill('Manual','gray')}</td><td>${r.active?pill('Ativa','green'):pill('Inativa','red')}</td><td>${esc(r.description||'—')}</td><td><button class="btn secondary sm edit-rule" data-id="${r.id}">Editar</button></td></tr>`).join('')}</tbody></table></div>`:empty('Sem regras definidas','Cria os motivos de multa que queres usar na equipa.')}`;$('#addFineRule').onclick=()=>openFineRule();$$('.edit-rule').forEach(b=>b.onclick=()=>openFineRule(b.dataset.id))}
function openFineRule(id=''){const rule=id?state.fineRules.find(x=>x.id===id):{reason:'',amount:2,automatic:false,active:true,description:'',code:''};openModal(id?'Editar regra de multa':'Nova regra de multa','Configura os motivos de multa e o respetivo valor.',`<form id="fineRuleForm"><div class="form-grid"><div class="field"><label>Motivo</label><input name="reason" value="${esc(rule.reason||'')}" required></div><div class="field"><label>Valor (€)</label><input type="number" step="0.01" min="0" name="amount" value="${esc(rule.amount??0)}" required></div><div class="field"><label>Tipo</label><select name="automatic"><option value="false" ${!rule.automatic?'selected':''}>Manual</option><option value="true" ${rule.automatic?'selected':''}>Automática</option></select></div><div class="field"><label>Estado</label><select name="active"><option value="true" ${rule.active?'selected':''}>Ativa</option><option value="false" ${!rule.active?'selected':''}>Inativa</option></select></div><div class="field full"><label>Descrição</label><textarea name="description" placeholder="Ex.: aplicada quando um jogador chega atrasado ao treino.">${esc(rule.description||'')}</textarea></div></div><div class="form-actions">${id&&rule.code!=='training_late'?'<button type="button" class="btn danger" id="deleteFineRule">Eliminar</button><span style="flex:1"></span>':''}<button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn">Guardar</button></div></form>`);$('#fineRuleForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target);const data={reason:fd.get('reason'),amount:Number(fd.get('amount')||0),automatic:fd.get('automatic')==='true',active:fd.get('active')==='true',description:fd.get('description'),code:rule.code||''};if(id)Object.assign(rule,data);else state.fineRules.push({id:uid('fr'),...data});closeModal();saveState('Regra de multa guardada.')};$('#deleteFineRule')&&($('#deleteFineRule').onclick=()=>{if(confirm('Eliminar esta regra?')){state.fineRules=state.fineRules.filter(x=>x.id!==rule.id);closeModal();saveState('Regra eliminada.')}});$('[data-close]').onclick=closeModal}

function renderSeasons(){$('#view-seasons').innerHTML=`<div class="section-head"><div><h2>Épocas</h2><p>Arquivo de jogos, treinos e estatísticas.</p></div><button class="btn" id="addSeason">＋ Nova época</button></div><div class="grid equal2">${state.seasons.map(s=>`<div class="card"><div class="card-head"><div><h3>${esc(s.label)}</h3><p>${state.games.filter(g=>g.seasonId===s.id).length} jogos · ${state.trainings.filter(t=>t.seasonId===s.id).length} treinos · ${(state.competitionResults||[]).filter(r=>r.seasonId===s.id).length} resultados</p></div>${s.id===state.settings.activeSeasonId?pill('Ativa','green'):pill(s.archived?'Arquivo':'Disponível','gray')}</div><div class="inline-actions"><button class="btn secondary sm set-season" data-id="${s.id}">Abrir época</button>${s.id!==state.settings.activeSeasonId?`<button class="btn secondary sm archive-season" data-id="${s.id}">${s.archived?'Reativar':'Arquivar'}</button>`:''}</div></div>`).join('')}</div>`;$('#addSeason').onclick=()=>{const label=prompt('Ex.: 2025/26');if(!label)return;const s={id:uid('s'),label,active:false,archived:false};state.seasons.push(s);saveState('Época criada.')};$$('.set-season').forEach(b=>b.onclick=()=>{state.settings.activeSeasonId=b.dataset.id;saveState();showView('dashboard')});$$('.archive-season').forEach(b=>b.onclick=()=>{const s=state.seasons.find(x=>x.id===b.dataset.id);s.archived=!s.archived;saveState()})}

function renderPeople(){const roles=['player','captain','staff','admin','member'];$('#view-people').innerHTML=`<div class="section-head"><div><h2>Pessoas e acessos</h2><p>Uma pessoa pode acumular várias funções na mesma conta.</p></div><button class="btn" id="addUser">＋ Pessoa</button></div><div class="info-strip">Exemplo: a conta do David pode ter simultaneamente Jogador + Equipa técnica + Admin. As permissões acumulam-se, não é necessário criar contas separadas.</div><div style="height:12px"></div><div class="table-wrap"><table><thead><tr><th>Pessoa</th><th>Funções</th><th>Jogador associado</th><th>Sócio nº</th><th></th></tr></thead><tbody>${state.users.map(u=>`<tr><td><strong>${esc(u.name)}</strong><div class="meta">${esc(u.email||'Sem email')}</div></td><td><div class="tags">${u.roles.map(r=>pill(roleLabel(r),r==='admin'?'purple':r==='staff'?'blue':r==='captain'?'amber':r==='player'?'green':'gray')).join('')}</div></td><td>${esc(playerById(u.playerId)?.name||'—')}</td><td>${esc(u.memberNumber||'—')}</td><td><button class="btn secondary sm edit-user" data-id="${u.id}">Editar</button></td></tr>`).join('')}</tbody></table></div>`;$('#addUser').onclick=()=>openUser();$$('.edit-user').forEach(b=>b.onclick=()=>openUser(b.dataset.id))}
function openUser(id=''){const u=id?state.users.find(x=>x.id===id):{name:'',email:'',roles:[],playerId:'',memberNumber:'',active:true};const po=state.players.map(p=>`<option value="${p.id}" ${u.playerId===p.id?'selected':''}>${esc(p.name)}</option>`).join('');openModal(id?'Editar pessoa':'Nova pessoa','Funções acumuláveis na mesma conta.',`<form id="userForm"><div class="form-grid"><div class="field"><label>Nome</label><input name="name" value="${esc(u.name)}" required></div><div class="field"><label>Email</label><input type="email" name="email" value="${esc(u.email||'')}"></div><div class="field"><label>Jogador associado</label><select name="playerId"><option value="">— Nenhum —</option>${po}</select></div><div class="field"><label>N.º sócio</label><input name="memberNumber" value="${esc(u.memberNumber||'')}"></div><div class="field full"><label>Funções</label><div class="checkboxes">${['player','captain','staff','admin','member'].map(r=>`<label class="check-pill"><input type="checkbox" name="roles" value="${r}" ${u.roles.includes(r)?'checked':''}>${roleLabel(r)}</label>`).join('')}</div></div></div><div class="form-actions"><button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn">Guardar</button></div></form>`);$('#userForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target);const data={name:fd.get('name'),email:fd.get('email'),playerId:fd.get('playerId'),memberNumber:fd.get('memberNumber'),roles:fd.getAll('roles'),active:true};if(id)Object.assign(u,data);else state.users.push({id:uid('u'),...data});closeModal();saveState('Acessos atualizados.')};$('[data-close]').onclick=closeModal}

function renderSettings(){
 const diag={players:state.players.length,games:state.games.length,trainings:state.trainings.length,results:state.competitionResults.length,seasons:state.seasons.length};const autoSnap=autoBackupSnapshot();
 $('#view-settings').innerHTML=`<div class="settings-stack"><div class="card"><div class="card-head"><div><h3>Plano alimentar pré-jogo</h3><p>Base para a notificação enviada aos convocados na véspera.</p></div>${pill(state.settings.nutritionEnabled?'Ativo':'A aguardar plano',state.settings.nutritionEnabled?'green':'amber')}</div><div class="form-grid"><div class="field"><label>Peso de referência</label><select id="weightReference"><option value="pre" ${state.settings.weightReference==='pre'?'selected':''}>Peso pré-treino</option><option value="post" ${state.settings.weightReference==='post'?'selected':''}>Peso pós-treino</option><option value="mean" ${state.settings.weightReference==='mean'?'selected':''}>Média pré/pós</option></select></div><div class="field full"><label>Template do plano alimentar</label><textarea id="nutritionTemplate" placeholder="Mais tarde colocamos aqui o plano que vais fornecer. Variáveis disponíveis: {{peso_medio}}, {{jogador}}, {{adversario}}, {{data_jogo}}, {{hora_jogo}}.">${esc(state.settings.nutritionTemplate||'')}</textarea></div></div><div class="form-actions"><button class="btn" id="saveNutrition">Guardar configuração</button></div></div><div class="card"><div class="card-head"><div><h3>Classificação da competição</h3><p>Calculada localmente a partir dos resultados da competição.</p></div>${pill('Manual + automática','green')}</div><div class="note">Os resultados dos restantes clubes são introduzidos em <strong>Resultados</strong>. Os jogos do ADC Figueiras entram automaticamente assim que tiverem resultado e estiverem marcados para contar para a classificação.</div><div class="form-actions"><button class="btn secondary" id="openSeriesResultsSettings">Gerir resultados</button></div></div><div class="card backup-card"><div class="card-head"><div><h3>Backup dos dados</h3><p>Faz um backup antes de cada atualização importante.</p></div>${pill(state.settings.lastBackupAt?`Último: ${fmtDateTime(state.settings.lastBackupAt)}`:'Nunca criado',state.settings.lastBackupAt?'green':'amber')}</div><div class="inline-actions"><button class="btn" id="exportData">Exportar backup JSON</button><button class="btn secondary" id="importData">Importar backup</button>${autoSnap?'<button class="btn secondary" id="exportAutoBackup">Exportar snapshot automático</button>':''}</div>${autoSnap?`<div class="meta backup-meta">Snapshot automático local: ${fmtDateTime(autoSnap.savedAt)} · guarda o estado anterior à última alteração.</div>`:''}</div><div class="card"><div class="card-head"><div><h3>Diagnóstico da aplicação</h3><p>Resumo rápido para confirmar que os dados estão intactos.</p></div><span class="pill blue">v${APP_VERSION}</span></div><div class="diagnostic-grid"><div><span>Época ativa</span><strong>${esc(activeSeason()?.label||'—')}</strong></div><div><span>Jogadores</span><strong>${diag.players}</strong></div><div><span>Jogos Figueiras</span><strong>${diag.games}</strong></div><div><span>Treinos</span><strong>${diag.trainings}</strong></div><div><span>Jogos/resultados série</span><strong>${diag.results}</strong></div><div><span>Épocas guardadas</span><strong>${diag.seasons}</strong></div></div></div><div class="card"><div class="card-head"><div><h3>Backend / sincronização</h3><p>Próxima grande etapa da aplicação.</p></div></div><div class="warning-strip">Esta build ainda guarda os dados no dispositivo. A futura base de dados online permitirá contas reais, sincronização entre dispositivos, backups centrais e notificações push.</div></div><div class="card danger-zone"><div class="card-head"><div><h3>Dados locais</h3><p>Operação irreversível sem backup.</p></div></div><button class="btn danger" id="resetData">Repor V2</button></div></div>`;$('#openSeriesResultsSettings').onclick=()=>showView('seriesResults');$('#saveNutrition').onclick=()=>{state.settings.weightReference=$('#weightReference').value;state.settings.nutritionTemplate=$('#nutritionTemplate').value.trim();state.settings.nutritionEnabled=!!state.settings.nutritionTemplate;saveState('Configuração guardada.')};$('#exportData').onclick=exportData;$('#importData').onclick=()=>$('#importInput').click();$('#exportAutoBackup')&&($('#exportAutoBackup').onclick=exportAutoBackup);$('#resetData').onclick=()=>{if(confirm('Apagar os dados da V2 neste dispositivo?')){state=defaultState();saveState('Dados repostos.')}}
}
function exportData(){state.settings.lastBackupAt=new Date().toISOString();localStorage.setItem(V2_KEY,JSON.stringify(state));const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`adc-figueiras-backup-${nowKey()}.json`;a.click();URL.revokeObjectURL(a.href);renderView(currentView);toast('Backup exportado.')}
function exportAutoBackup(){const snap=autoBackupSnapshot();if(!snap?.data){toast('Ainda não existe snapshot automático.');return}const blob=new Blob([JSON.stringify(snap.data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`adc-figueiras-snapshot-${nowKey()}.json`;a.click();URL.revokeObjectURL(a.href);toast('Snapshot automático exportado.')}

function openModal(title,subtitle,html,wide=false){$('#modalTitle').textContent=title;$('#modalSubtitle').textContent=subtitle||'';$('#modalBody').innerHTML=html;$('#modal').classList.toggle('wide',!!wide);$('#modalBackdrop').classList.remove('hidden')}
function closeModal(){$('#modalBackdrop').classList.add('hidden')}

document.addEventListener('click',e=>{const link=e.target.closest('[data-team-link]');if(link){e.preventDefault();e.stopPropagation();openTeamPage(link.dataset.teamLink)}});
$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#closeModal').onclick=closeModal;$('#modalBackdrop').onclick=e=>{if(e.target===$('#modalBackdrop'))closeModal()};$('#previewMode').onchange=e=>{mode=e.target.value;localStorage.setItem(MODE_KEY,mode);if(!can(currentView))currentView='dashboard';renderChrome();showView(currentView)};$('#seasonSelect').onchange=e=>{state.settings.activeSeasonId=e.target.value;saveState();showView('dashboard')};$('#notificationBell').onclick=()=>showView('notifications');$('#importInput').onchange=e=>{const file=e.target.files[0];if(!file)return;const r=new FileReader();r.onload=()=>{try{const data=JSON.parse(r.result);if(!data.schemaVersion)throw new Error('Formato inválido');state=normalizeState(data);saveState('Backup importado.')}catch(err){alert('Não foi possível importar este ficheiro.')}};r.readAsText(file);e.target.value=''};
window.addEventListener('online',()=>$('#offlineBanner').classList.add('hidden'));window.addEventListener('offline',()=>$('#offlineBanner').classList.remove('hidden'));if(!navigator.onLine)$('#offlineBanner').classList.remove('hidden');
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});

renderChrome();showView('dashboard');
